import{_ as l,o as a,c as i,at as o}from"./chunks/framework.CY22Hent.js";const p=JSON.parse('{"title":"域名和证书笔记","description":"","frontmatter":{"title":"域名和证书笔记","date":"2026-05-26T00:00:00.000Z","lastUpdated":"2026-05-26T00:00:00.000Z","categories":["服务器"],"tags":["域名和证书","服务器"]},"headers":[],"relativePath":"blogs/服务器/域名和证书笔记.md","filePath":"blogs/服务器/域名和证书笔记.md"}'),r={name:"blogs/服务器/域名和证书笔记.md"};function e(s,t,n,d,h,c){return a(),i("div",null,[...t[0]||(t[0]=[o(`<p>[toc]</p><h1 id="域名和证书" tabindex="-1">域名和证书 <a class="header-anchor" href="#域名和证书" aria-label="Permalink to &quot;域名和证书&quot;">​</a></h1><h2 id="域名" tabindex="-1">域名 <a class="header-anchor" href="#域名" aria-label="Permalink to &quot;域名&quot;">​</a></h2><h3 id="什么是域名" tabindex="-1">什么是域名 <a class="header-anchor" href="#什么是域名" aria-label="Permalink to &quot;什么是域名&quot;">​</a></h3><p>域名是互联网上用于标识和定位计算机的层次结构化字符标识，它将复杂的IP地址转换为人类易于记忆的名称。</p><p>例如，<code>www.example.com</code> 就是一个域名。</p><h3 id="为什么需要域名-前因后果" tabindex="-1">为什么需要域名（前因后果） <a class="header-anchor" href="#为什么需要域名-前因后果" aria-label="Permalink to &quot;为什么需要域名（前因后果）&quot;">​</a></h3><p><strong>背景</strong>：在互联网早期，用户需要通过IP地址来访问网站。IPv4地址由4组数字组成，如 <code>192.168.1.1</code>，这对人类来说很难记忆和输入。</p><p><strong>问题</strong>：</p><ul><li>IP地址难以记忆</li><li>IP地址可能会改变（服务器迁移、网络重构等）</li><li>一个IP地址可能对应多个服务</li></ul><p><strong>解决方案</strong>：域名系统（DNS）应运而生，将人类友好的名称映射到IP地址。</p><h3 id="域名-vs-ip地址" tabindex="-1">域名 vs IP地址 <a class="header-anchor" href="#域名-vs-ip地址" aria-label="Permalink to &quot;域名 vs IP地址&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>域名</th><th>IP地址</th></tr></thead><tbody><tr><td>可读性</td><td>人类友好，易记忆</td><td>数字组合，难记忆</td></tr><tr><td>稳定性</td><td>可指向不同IP</td><td>可能会改变</td></tr><tr><td>灵活性</td><td>支持负载均衡、CDN</td><td>直接路由</td></tr><tr><td>关系</td><td>通过DNS解析为IP</td><td>网络设备的实际地址</td></tr></tbody></table><p><strong>重要区别</strong>：</p><ul><li>一个域名可对应多个IP（负载均衡）</li><li>一个IP可对应多个域名（虚拟主机）</li><li>域名需要DNS解析，IP直接路由</li></ul><h3 id="域名的结构" tabindex="-1">域名的结构 <a class="header-anchor" href="#域名的结构" aria-label="Permalink to &quot;域名的结构&quot;">​</a></h3><p>域名采用层次结构，从右到左依次为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>顶级域名（TLD）</span></span>
<span class="line"><span>    └── 二级域名（SLD）</span></span>
<span class="line"><span>            └── 子域名</span></span></code></pre></div><p><strong>示例</strong>：<code>blog.example.com</code></p><ul><li><code>.com</code>：顶级域名</li><li><code>example</code>：二级域名</li><li><code>blog</code>：子域名</li></ul><h3 id="域名解析过程" tabindex="-1">域名解析过程 <a class="header-anchor" href="#域名解析过程" aria-label="Permalink to &quot;域名解析过程&quot;">​</a></h3><ol><li><strong>本地DNS缓存</strong>：首先检查本地缓存</li><li><strong>递归查询</strong>：向DNS服务器发起查询请求</li><li><strong>根域名服务器</strong>：返回顶级域名服务器地址</li><li><strong>顶级域名服务器</strong>：返回权威域名服务器地址</li><li><strong>权威域名服务器</strong>：返回最终的IP地址</li><li><strong>返回结果</strong>：将IP地址返回给客户端</li></ol><h3 id="常见的域名后缀" tabindex="-1">常见的域名后缀 <a class="header-anchor" href="#常见的域名后缀" aria-label="Permalink to &quot;常见的域名后缀&quot;">​</a></h3><ul><li><strong>通用顶级域名（gTLD）</strong>：<code>.com</code>、<code>.net</code>、<code>.org</code>、<code>.info</code> 等</li><li><strong>国家代码顶级域名（ccTLD）</strong>：<code>.cn</code>（中国）、<code>.us</code>（美国）、<code>.jp</code>（日本）等</li><li><strong>新通用顶级域名（New gTLD）</strong>：<code>.app</code>、<code>.dev</code>、<code>.xyz</code> 等</li></ul><h3 id="域名注册和管理" tabindex="-1">域名注册和管理 <a class="header-anchor" href="#域名注册和管理" aria-label="Permalink to &quot;域名注册和管理&quot;">​</a></h3><ul><li><strong>注册商</strong>：如阿里云、腾讯云、GoDaddy等</li><li><strong>DNS解析服务</strong>：可以与注册商相同，也可以使用第三方服务</li><li><strong>域名续费</strong>：通常需要每年续费，过期后可能被回收</li></ul><h2 id="ssl-tls证书" tabindex="-1">SSL/TLS证书 <a class="header-anchor" href="#ssl-tls证书" aria-label="Permalink to &quot;SSL/TLS证书&quot;">​</a></h2><h3 id="什么是ssl-tls证书" tabindex="-1">什么是SSL/TLS证书 <a class="header-anchor" href="#什么是ssl-tls证书" aria-label="Permalink to &quot;什么是SSL/TLS证书&quot;">​</a></h3><p>SSL/TLS证书是数字证书的一种，是遵守SSL协议的，由受信任的数字证书颁发机构（简称CA）在验证服务器身份后颁发，具有服务器身份验证和数据传输加密的功能。</p><p>网站安装SSL证书后，就会激活SSL协议。在客户端和服务端之间建立一条SSL安全通道（Secure socket layer(SSL)，对互相传送的数据进行加密和隐藏；确保数据在传送中不被改变，保证数据的完整性。</p><p>目前，像是很多大型的电商网站、外贸网站、企业网站都有安装SSL证书。而且用户可以通过服务器证书验证他所访问的网站是否是真实可靠。</p><h3 id="如何判断该网站是否安装了ssl证书" tabindex="-1">如何判断该网站是否安装了SSL证书 <a class="header-anchor" href="#如何判断该网站是否安装了ssl证书" aria-label="Permalink to &quot;如何判断该网站是否安装了SSL证书&quot;">​</a></h3><p>一般情况下，我们访问的Web网站都是以“http”开头的，如果网站安装SSL证书之后，那么Web网站能够以“https”开头进行访问，而且URL地址前面还有小锁的符号。</p><h3 id="为什么需要证书-前因后果" tabindex="-1">为什么需要证书（前因后果） <a class="header-anchor" href="#为什么需要证书-前因后果" aria-label="Permalink to &quot;为什么需要证书（前因后果）&quot;">​</a></h3><p><strong>背景</strong>：HTTP协议是明文传输的，数据在传输过程中可能被窃听、篡改或伪造。</p><p><strong>问题</strong>：</p><ul><li>数据泄露：密码、信用卡信息等敏感数据可能被截获</li><li>数据篡改：传输的内容可能被恶意修改</li><li>身份伪造：攻击者可以伪造网站，欺骗用户</li></ul><p><strong>解决方案</strong>：HTTPS协议通过SSL/TLS证书实现加密传输和身份验证。</p><h3 id="证书的原理" tabindex="-1">证书的原理 <a class="header-anchor" href="#证书的原理" aria-label="Permalink to &quot;证书的原理&quot;">​</a></h3><ol><li><strong>非对称加密</strong>：使用公钥和私钥对</li><li><strong>数字签名</strong>：证书颁发机构（CA）对证书进行签名</li><li><strong>证书链</strong>：从根证书到中间证书到服务器证书的信任链</li><li><strong>握手过程</strong>：客户端验证服务器证书，协商加密算法</li></ol><h3 id="证书链和根证书" tabindex="-1">证书链和根证书 <a class="header-anchor" href="#证书链和根证书" aria-label="Permalink to &quot;证书链和根证书&quot;">​</a></h3><p><strong>证书链结构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根证书（Root CA）</span></span>
<span class="line"><span>    └── 中间证书（Intermediate CA）</span></span>
<span class="line"><span>            └── 服务器证书（Server Certificate）</span></span></code></pre></div><p><strong>重要性</strong>：</p><ul><li>客户端需要完整的证书链才能验证证书</li><li>缺少中间证书会导致证书验证失败</li><li>根证书通常预装在操作系统或浏览器中</li></ul><h3 id="证书的类型" tabindex="-1">证书的类型 <a class="header-anchor" href="#证书的类型" aria-label="Permalink to &quot;证书的类型&quot;">​</a></h3><h4 id="按验证级别分类" tabindex="-1">按验证级别分类 <a class="header-anchor" href="#按验证级别分类" aria-label="Permalink to &quot;按验证级别分类&quot;">​</a></h4><p>SSL证书分为3种：域名型SSL证书（DV SSL），企业组织型SSL证书（OV SSL），增强型SSL证书（EV SSL）</p><ol><li><p><strong>域名验证（DV）证书</strong></p><ul><li>只验证域名所有权。</li><li>此类证书仅能起到网站机密信息加密的作用，无法向用户证明网站的真实身份。</li><li>颁发速度快</li><li>适用于个人网站、小型组织或企业网站、各类加密应用（如数据库和即时通讯协议等）。</li></ul></li><li><p><strong>组织验证（OV）证书</strong></p><ul><li>验证域名所有权和组织单位的真实身份。</li><li>不仅能起到网站机密信息加密的作用，而且能向用户证明网站的真实身份。</li><li>适用于企业网站，电子商务网站使用。因为需要的是在线信任和在线安全。</li></ul></li><li><p><strong>增强验证（EV）证书</strong></p><ul><li>最严格的验证流程。验证流程更加具体详细，验证步骤更多，证书所绑定的网站就更加的可靠，可信。</li><li>浏览器地址栏显示组织名称，还有公司地址等等；</li><li>特别适合金融、保险、p2p、电商、网上支付等等等高安全要求网站。</li></ul></li></ol><blockquote><p><strong>DV vs OV vs EV</strong>证书的区别：</p></blockquote><ul><li>安全级别相同（加密强度）</li><li>验证级别不同（域名→组织→扩展验证）</li><li>显示效果不同（EV证书在地址栏显示组织名称）</li><li>价格不同（EV最贵，DV最便宜或免费）</li></ul><h4 id="按覆盖范围分类" tabindex="-1">按覆盖范围分类 <a class="header-anchor" href="#按覆盖范围分类" aria-label="Permalink to &quot;按覆盖范围分类&quot;">​</a></h4><ol><li><strong>单域名证书</strong>：只保护一个域名</li><li><strong>多域名证书（SAN）</strong>：保护多个域名</li><li><strong>通配符证书</strong>：保护主域名及其所有子域名</li></ol><blockquote><p><strong>单域名 vs 多域名 vs 通配符</strong>证书的区别：</p></blockquote><ul><li>覆盖范围不同（单个域名→多个域名→主域名及所有子域名）</li><li>价格不同（通配符最贵）</li><li>灵活性不同（多域名最灵活）</li></ul><h4 id="免费证书-vs-付费证书" tabindex="-1">免费证书 vs 付费证书 <a class="header-anchor" href="#免费证书-vs-付费证书" aria-label="Permalink to &quot;免费证书 vs 付费证书&quot;">​</a></h4><table tabindex="0"><thead><tr><th>特性</th><th>免费证书（Let&#39;s Encrypt）</th><th>付费证书</th></tr></thead><tbody><tr><td>费用</td><td>免费</td><td>需要付费</td></tr><tr><td>验证级别</td><td>仅DV</td><td>支持OV/EV</td></tr><tr><td>有效期</td><td>90天</td><td>1年或更长</td></tr><tr><td>自动续期</td><td>支持</td><td>部分支持</td></tr><tr><td>技术支持</td><td>社区支持</td><td>专业支持</td></tr><tr><td>保险</td><td>无</td><td>有</td></tr><tr><td>适用场景</td><td>个人网站、测试环境</td><td>企业网站、金融电商</td></tr></tbody></table><h3 id="证书的申请、部署和管理" tabindex="-1">证书的申请、部署和管理 <a class="header-anchor" href="#证书的申请、部署和管理" aria-label="Permalink to &quot;证书的申请、部署和管理&quot;">​</a></h3><h4 id="申请流程" tabindex="-1">申请流程 <a class="header-anchor" href="#申请流程" aria-label="Permalink to &quot;申请流程&quot;">​</a></h4><ol><li><strong>生成CSR（证书签名请求）</strong>：包含公钥和组织信息</li><li><strong>提交给CA</strong>：选择证书颁发机构</li><li><strong>验证身份</strong>：根据证书类型进行相应验证</li><li><strong>颁发证书</strong>：CA签发证书文件</li><li><strong>部署证书</strong>：在服务器上配置证书</li></ol><h4 id="部署位置" tabindex="-1">部署位置 <a class="header-anchor" href="#部署位置" aria-label="Permalink to &quot;部署位置&quot;">​</a></h4><ul><li>Web服务器（Nginx、Apache等）</li><li>负载均衡器</li><li>CDN服务</li><li>API网关</li></ul><h4 id="续期和管理" tabindex="-1">续期和管理 <a class="header-anchor" href="#续期和管理" aria-label="Permalink to &quot;续期和管理&quot;">​</a></h4><ul><li><strong>有效期</strong>：通常为1年或90天（Let&#39;s Encrypt）</li><li><strong>自动续期</strong>：使用ACME协议实现自动续期（Certbot、acme.sh、Caddy等）</li><li><strong>证书监控</strong>：监控证书过期时间，及时续期</li><li><strong>密钥轮换</strong>：定期更换私钥，提高安全性</li></ul><h2 id="域名和证书的关系" tabindex="-1">域名和证书的关系 <a class="header-anchor" href="#域名和证书的关系" aria-label="Permalink to &quot;域名和证书的关系&quot;">​</a></h2><p><strong>重要概念</strong>：域名和证书是两个完全独立的概念和服务，它们之间的关系如下：</p><ol><li><p><strong>独立性</strong>：</p><ul><li>域名：用于标识和定位网站，由域名注册商管理</li><li>证书：用于加密传输和身份验证，由证书颁发机构（CA）管理</li><li>购买域名时不会自动获得证书，需要单独申请</li></ul></li><li><p><strong>关联性</strong>：</p><ul><li>证书必须绑定到具体的域名才能使用</li><li>证书申请时需要证明对域名的所有权</li><li>一个域名可以有多个证书（不同类型、不同有效期）</li></ul></li><li><p><strong>使用场景</strong>：</p><ul><li>可以有域名但没有证书（HTTP访问）</li><li>可以有证书但没有域名（IP访问，较少见）</li><li>正常网站需要同时拥有域名和证书（HTTPS访问）</li></ul></li></ol><p><strong>类比理解</strong>：</p><ul><li>域名就像&quot;门牌号&quot;，告诉别人你的地址</li><li>证书就像&quot;身份证&quot;，证明你的身份</li><li>两者都需要才能安全访问网站</li></ul><h2 id="常见错误和解决方案" tabindex="-1">常见错误和解决方案 <a class="header-anchor" href="#常见错误和解决方案" aria-label="Permalink to &quot;常见错误和解决方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误类型</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td>证书过期</td><td>证书有效期已过</td><td>及时续期或设置自动续期</td></tr><tr><td>域名不匹配</td><td>证书域名与访问域名不一致</td><td>确保证书包含所有需要的域名</td></tr><tr><td>证书链不完整</td><td>缺少中间证书</td><td>配置完整的证书链</td></tr><tr><td>混合内容</td><td>HTTPS页面包含HTTP资源</td><td>将所有资源改为HTTPS</td></tr><tr><td>DNS解析失败</td><td>DNS配置错误或未生效</td><td>检查DNS配置，等待传播完成</td></tr><tr><td>证书验证失败</td><td>验证记录配置错误</td><td>检查TXT记录或验证文件</td></tr></tbody></table><h2 id="ssl证书中-如何把xxx-chain-crt和xxx-public-crt-合并为xxx-pem-文件" tabindex="-1">SSL证书中 如何把xxx_chain.crt和xxx_public.crt 合并为xxx.pem 文件 <a class="header-anchor" href="#ssl证书中-如何把xxx-chain-crt和xxx-public-crt-合并为xxx-pem-文件" aria-label="Permalink to &quot;SSL证书中 如何把xxx_chain.crt和xxx_public.crt 合并为xxx.pem 文件&quot;">​</a></h2><p>把xxxxxxx_public.crt 和 xxxxxxx_chain.crt合并成一个.pem 文件。</p><p>方法：直接txt打开两个文件，复制内容保存成一个文件，命名为.pem文件格式即可。需要注意的是xxxxxxx_public.crt内容放前面，不要留空行。</p><h2 id="域名和证书的完整使用流程" tabindex="-1">域名和证书的完整使用流程 <a class="header-anchor" href="#域名和证书的完整使用流程" aria-label="Permalink to &quot;域名和证书的完整使用流程&quot;">​</a></h2><h3 id="从购买域名到网站上线" tabindex="-1">从购买域名到网站上线 <a class="header-anchor" href="#从购买域名到网站上线" aria-label="Permalink to &quot;从购买域名到网站上线&quot;">​</a></h3><h4 id="第一步-购买域名" tabindex="-1">第一步：购买域名 <a class="header-anchor" href="#第一步-购买域名" aria-label="Permalink to &quot;第一步：购买域名&quot;">​</a></h4><ol><li><strong>选择域名注册商</strong>：阿里云、腾讯云、GoDaddy、Namecheap等</li><li><strong>查询域名可用性</strong>：输入想要的域名，检查是否已被注册</li><li><strong>选择域名后缀</strong>：<code>根据需求选择.com</code>、.cn、.net等</li><li><strong>完成购买</strong>：填写注册信息，支付费用</li><li><strong>域名实名认证</strong>（国内注册商）：提交身份证或企业资质</li></ol><h4 id="第二步-配置dns解析" tabindex="-1">第二步：配置DNS解析 <a class="header-anchor" href="#第二步-配置dns解析" aria-label="Permalink to &quot;第二步：配置DNS解析&quot;">​</a></h4><p><strong>为什么需要添加DNS记录</strong>：</p><ul><li>域名本身只是一个名称，需要通过DNS解析指向具体的服务器IP地址</li><li>添加记录相当于在互联网的&quot;电话簿&quot;中登记你的地址</li><li>没有DNS记录，域名无法访问到你的服务器</li></ul><p><strong>DNS记录类型和作用</strong>：</p><table tabindex="0"><thead><tr><th>记录类型</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td>A记录</td><td>域名指向IPv4地址</td><td><code>www</code> → <code>192.168.1.1</code></td></tr><tr><td>AAAA记录</td><td>域名指向IPv6地址</td><td><code>www</code> → <code>2001:db8::1</code></td></tr><tr><td>CNAME记录</td><td>域名别名，指向另一个域名</td><td><code>blog</code> → <code>www.example.com</code></td></tr><tr><td>MX记录</td><td>邮件服务器记录</td><td><code>@</code> → <code>mail.example.com</code></td></tr><tr><td>TXT记录</td><td>文本记录，用于验证等</td><td><code>@</code> → <code>v=spf1 include:_spf.google.com ~all</code></td></tr><tr><td>NS记录</td><td>指定域名服务器</td><td><code>@</code> → <code>ns1.aliyun.com</code></td></tr></tbody></table><p><strong>配置步骤</strong>：</p><ol><li>登录域名控制台</li><li>找到DNS解析或域名解析页面</li><li>添加A记录：主机记录填写<code>@</code>或<code>www</code>，记录值填写服务器IP地址</li><li>等待DNS生效（通常10分钟-24小时）</li><li>使用<code>ping</code>或<code>nslookup</code>命令验证解析是否成功</li></ol><h4 id="第三步-准备服务器" tabindex="-1">第三步：准备服务器 <a class="header-anchor" href="#第三步-准备服务器" aria-label="Permalink to &quot;第三步：准备服务器&quot;">​</a></h4><ol><li><strong>购买/租用服务器</strong>：云服务器（ECS）、VPS、物理服务器等</li><li><strong>配置服务器环境</strong>：安装Web服务器（Nginx、Apache等）</li><li><strong>部署网站代码</strong>：上传网站文件到服务器</li><li><strong>测试HTTP访问</strong>：通过IP地址访问，确保网站正常运行</li></ol><h4 id="第四步-申请ssl证书" tabindex="-1">第四步：申请SSL证书 <a class="header-anchor" href="#第四步-申请ssl证书" aria-label="Permalink to &quot;第四步：申请SSL证书&quot;">​</a></h4><p><strong>证书申请流程</strong>：</p><ol><li><p><strong>选择证书类型</strong>：</p><ul><li>个人/测试：免费DV证书（Let&#39;s Encrypt）</li><li>企业网站：付费OV证书</li><li>金融/电商：付费EV证书</li></ul></li><li><p><strong>申请证书</strong>：</p><ul><li><strong>方式一：云平台免费证书</strong>（推荐新手） <ul><li>登录云平台证书控制台</li><li>申请免费证书</li><li>选择域名验证方式</li></ul></li><li><strong>方式二：Let&#39;s Encrypt</strong><ul><li>使用Certbot工具</li><li>自动验证和部署</li></ul></li><li><strong>方式三：付费证书</strong><ul><li>向CA机构申请</li><li>提交企业资料</li><li>等待审核</li></ul></li></ul></li><li><p><strong>域名验证</strong>（证明域名所有权）：</p><ul><li><strong>DNS验证</strong>：在域名控制台添加TXT记录</li><li><strong>文件验证</strong>：在网站根目录放置验证文件</li><li><strong>HTTP验证</strong>：通过特定URL验证</li></ul></li><li><p><strong>下载证书</strong>：获得证书文件和私钥文件</p></li></ol><h4 id="第五步-部署证书到服务器" tabindex="-1">第五步：部署证书到服务器 <a class="header-anchor" href="#第五步-部署证书到服务器" aria-label="Permalink to &quot;第五步：部署证书到服务器&quot;">​</a></h4><ol><li><strong>上传证书文件</strong>：将证书和私钥上传到服务器</li><li><strong>配置Web服务器</strong>：<div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    listen </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">443</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ssl;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    server_name </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">www.example.com;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ssl_certificate </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/cert.pem;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ssl_certificate_key </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/path/to/key.pem;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><strong>重启Web服务器</strong>：使配置生效</li><li><strong>测试HTTPS访问</strong>：通过<a href="https://xn--5tzm5gz6m7hk" target="_blank" rel="noreferrer">https://访问网站</a></li><li><strong>配置HTTP跳转HTTPS</strong>：将HTTP请求重定向到HTTPS</li></ol><h4 id="第六步-验证和优化" tabindex="-1">第六步：验证和优化 <a class="header-anchor" href="#第六步-验证和优化" aria-label="Permalink to &quot;第六步：验证和优化&quot;">​</a></h4><ol><li><strong>检查证书状态</strong>：使用浏览器查看证书信息</li><li><strong>SSL测试</strong>：使用SSL Labs等工具测试配置</li><li><strong>安全配置</strong>：启用HSTS、配置安全头部</li><li><strong>监控续期</strong>：设置证书自动续期</li></ol><h2 id="为什么云平台有域名控制台和证书控制台" tabindex="-1">为什么云平台有域名控制台和证书控制台 <a class="header-anchor" href="#为什么云平台有域名控制台和证书控制台" aria-label="Permalink to &quot;为什么云平台有域名控制台和证书控制台&quot;">​</a></h2><blockquote><p>常见云平台对比</p></blockquote><table tabindex="0"><thead><tr><th>平台</th><th>域名服务</th><th>证书服务</th><th>免费证书</th><th>特点</th></tr></thead><tbody><tr><td>阿里云</td><td>云解析DNS</td><td>SSL证书服务</td><td>单域名</td><td>功能全面，文档详细</td></tr><tr><td>腾讯云</td><td>DNSPod</td><td>SSL证书</td><td>单域名</td><td>操作简单，界面友好</td></tr><tr><td>华为云</td><td>域名服务</td><td>SSL证书管理</td><td>单域名</td><td>企业级服务</td></tr><tr><td>Cloudflare</td><td>DNS管理</td><td>SSL/TLS</td><td>通配符</td><td>全球CDN，安全性高</td></tr></tbody></table><h3 id="域名控制台操作的原因" tabindex="-1">域名控制台操作的原因： <a class="header-anchor" href="#域名控制台操作的原因" aria-label="Permalink to &quot;域名控制台操作的原因：&quot;">​</a></h3><ol><li><strong>DNS权威性</strong>：域名控制台提供权威的DNS解析服务</li><li><strong>域名所有权</strong>：只有域名所有者才能修改DNS记录</li><li><strong>全球生效</strong>：修改会在全球DNS服务器上生效</li><li><strong>安全控制</strong>：防止DNS劫持和恶意修改</li></ol><h3 id="证书控制台操作的原因" tabindex="-1">证书控制台操作的原因： <a class="header-anchor" href="#证书控制台操作的原因" aria-label="Permalink to &quot;证书控制台操作的原因：&quot;">​</a></h3><ol><li><strong>证书管理</strong>：集中管理所有证书</li><li><strong>验证流程</strong>：完成域名验证和企业验证</li><li><strong>部署便捷</strong>：一键部署到云服务</li><li><strong>监控提醒</strong>：自动监控证书状态和到期时间</li></ol><h3 id="两个控制台的协作" tabindex="-1">两个控制台的协作： <a class="header-anchor" href="#两个控制台的协作" aria-label="Permalink to &quot;两个控制台的协作：&quot;">​</a></h3><ol><li><strong>申请证书时</strong>：在证书控制台申请一个新证书，然后需要在域名控制台中添加验证记录</li><li><strong>部署证书时</strong>：在证书控制台下载证书文件，在服务器上配置</li><li><strong>续期证书时</strong>：在证书控制台续期证书，可能需要在域名控制台上进行重新验证。</li></ol><h2 id="实际操作示例" tabindex="-1">实际操作示例 <a class="header-anchor" href="#实际操作示例" aria-label="Permalink to &quot;实际操作示例&quot;">​</a></h2><h3 id="示例1-个人博客-阿里云" tabindex="-1">示例1：个人博客（阿里云） <a class="header-anchor" href="#示例1-个人博客-阿里云" aria-label="Permalink to &quot;示例1：个人博客（阿里云）&quot;">​</a></h3><p>购买域名 → 配置DNS解析（A记录）→ 购买ECS → 部署WordPress → 申请免费证书 → DNS验证 → 部署证书 → 测试HTTPS访问</p><h3 id="示例2-企业官网-腾讯云" tabindex="-1">示例2：企业官网（腾讯云） <a class="header-anchor" href="#示例2-企业官网-腾讯云" aria-label="Permalink to &quot;示例2：企业官网（腾讯云）&quot;">​</a></h3><p>购买域名 → 配置DNS（A/CNAME/MX记录）→ 购买CVM → 部署网站代码 → 申请OV证书 → 企业验证 → 部署证书 → 安全加固</p><h3 id="示例3-使用cloudflare" tabindex="-1">示例3：使用Cloudflare <a class="header-anchor" href="#示例3-使用cloudflare" aria-label="Permalink to &quot;示例3：使用Cloudflare&quot;">​</a></h3><p>购买域名 → 添加到Cloudflare → 修改NS记录 → 配置DNS → 启用SSL → 配置源站 → 通过CDN访问</p><h2 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h2><p><strong>Q1：购买域名后为什么不能直接访问？</strong> 域名只是名称，需要配置DNS解析指向服务器IP才能访问，就像有了门牌号还需要在地图上登记位置。</p><p><strong>Q2：为什么证书申请需要验证域名？</strong> 为防止恶意申请，CA需要确认申请者拥有域名控制权，保证证书安全性。</p><p><strong>Q3：DNS解析为什么要等这么久？</strong> DNS记录修改后需在全球DNS服务器传播，通常10分钟-24小时，取决于TTL设置。</p><p><strong>Q4：免费证书和付费证书有什么区别？</strong> 主要区别在验证级别、有效期、技术支持。免费证书只验证域名，付费证书可验证企业身份。</p><p><strong>Q5：为什么需要在不同控制台添加记录？</strong> 域名和证书是不同服务，域名控制台管理DNS解析，证书控制台管理证书申请和部署。</p><p><strong>Q6：一个域名可以有多个证书吗？</strong> 可以。一个域名可同时拥有多个证书，如主站和子域名使用不同证书。</p><p><strong>Q7：证书过期了怎么办？</strong> 需重新申请并部署。建议设置自动续期，避免证书过期导致网站无法访问。</p><p><strong>Q8：为什么HTTPS网站还会显示不安全？</strong> 可能原因：证书过期、域名不匹配、证书链不完整、混合内容（HTTP资源）等。</p><p><strong>Q9：可以在不同平台管理域名和证书吗？</strong> 可以。域名可在阿里云，证书可在腾讯云，只要DNS解析正确配置即可。</p><p><strong>Q10：什么是域名锁定，为什么要开启？</strong> 域名锁定是安全措施，防止域名被恶意转移。建议开启以提高安全性。</p><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><h3 id="域名管理" tabindex="-1">域名管理 <a class="header-anchor" href="#域名管理" aria-label="Permalink to &quot;域名管理&quot;">​</a></h3><ol><li>使用强密码保护域名账户</li><li>启用域名锁定功能</li><li>设置域名自动续费</li><li>定期检查域名WHOIS信息</li><li>使用域名隐私保护服务</li></ol><h3 id="证书管理" tabindex="-1">证书管理 <a class="header-anchor" href="#证书管理" aria-label="Permalink to &quot;证书管理&quot;">​</a></h3><ol><li>优先使用HTTPS</li><li>选择合适的证书类型</li><li>配置完整的证书链</li><li>启用HSTS（HTTP Strict Transport Security）</li><li>定期检查证书安全配置（如SSL Labs测试）</li><li>使用自动续期工具</li><li>监控证书过期时间</li></ol><h3 id="安全建议" tabindex="-1">安全建议 <a class="header-anchor" href="#安全建议" aria-label="Permalink to &quot;安全建议&quot;">​</a></h3><ol><li>使用强加密算法（如TLS 1.2+）</li><li>禁用过时的加密套件</li><li>启用OCSP Stapling</li><li>定期更新服务器软件</li><li>实施安全头部（CSP、X-Frame-Options等）</li></ol>`,128)])])}const u=l(r,[["render",e]]);export{p as __pageData,u as default};
